import{_ as n}from"./chunks/files.B17OUyrr.js";import{_ as i,c as r,o as t,a2 as a}from"./chunks/framework.CIiVzG-O.js";const b=JSON.parse('{"title":"Dateien vergleichen","description":"Öffnen Sie zwei Dateien nebeneinander, lesen Sie farbig markierte Änderungen, springen Sie zwischen ihnen und bearbeiten oder teilen Sie.","frontmatter":{"title":"Dateien vergleichen","description":"Öffnen Sie zwei Dateien nebeneinander, lesen Sie farbig markierte Änderungen, springen Sie zwischen ihnen und bearbeiten oder teilen Sie."},"headers":[],"relativePath":"de/guide/files.md","filePath":"de/guide/files.md","lastUpdated":1794296122000}'),s={name:"de/guide/files.md"};function d(l,e,h,o,g,c){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="dateien-vergleichen" tabindex="-1">Dateien vergleichen <a class="header-anchor" href="#dateien-vergleichen" aria-label="Permalink to &quot;Dateien vergleichen&quot;">​</a></h1><p>Dies ist die Ansicht, mit der die meisten beginnen: zwei Versionen derselben Datei, nebeneinander, mit jeder markierten Abweichung.</p><img src="'+n+'" alt="Zwei Textdateien nebeneinander mit farbigen Änderungen" class="guide-shot"><h2 id="zwei-dateien-offnen" tabindex="-1">Zwei Dateien öffnen <a class="header-anchor" href="#zwei-dateien-offnen" aria-label="Permalink to &quot;Zwei Dateien öffnen&quot;">​</a></h2><p>Nutzen Sie <strong>Ablage → Öffnen</strong>, oder ziehen Sie einfach zwei Dateien ins qDiff-Fenster. Müssen Sie drei Versionen abgleichen? Fügen Sie ein drittes Feld hinzu — dieselben Farbregeln gelten. Kürzliche Vergleiche bleiben auf dem Begrüßungsbildschirm für das nächste Mal erhalten.</p><h2 id="was-die-farben-bedeuten" tabindex="-1">Was die Farben bedeuten <a class="header-anchor" href="#was-die-farben-bedeuten" aria-label="Permalink to &quot;Was die Farben bedeuten&quot;">​</a></h2><ul><li><strong>Zartes Rot</strong> — Inhalt auf dieser Seite wurde entfernt oder gehört zur älteren Version.</li><li><strong>Zartes Grün</strong> — Inhalt wurde hinzugefügt oder gehört zur neueren Version.</li><li><strong>Kräftigere Farbe innerhalb einer Zeile</strong> — genau die Wörter, die sich geändert haben. Ein einzelnes geändertes Wort geht nie in einer ganz eingefärbten Zeile unter.</li></ul><p>Beide Seiten scrollen gemeinsam, sodass die zwei Versionen immer in derselben Zeile bleiben.</p><h2 id="zwischen-anderungen-wechseln" tabindex="-1">Zwischen Änderungen wechseln <a class="header-anchor" href="#zwischen-anderungen-wechseln" aria-label="Permalink to &quot;Zwischen Änderungen wechseln&quot;">​</a></h2><p>Klicken Sie auf die schmale Übersicht neben dem Text, um an eine beliebige Stelle der Datei zu springen, oder nutzen Sie die Schalter für Zurück / Weiter (sie haben auch Tastenkürzel), um die Änderungen einzeln durchzugehen. Die Übersicht zeigt außerdem, wo Sie sich in einem langen Dokument befinden.</p><h2 id="unterwegs-korrigieren" tabindex="-1">Unterwegs korrigieren <a class="header-anchor" href="#unterwegs-korrigieren" aria-label="Permalink to &quot;Unterwegs korrigieren&quot;">​</a></h2><p>Beide Seiten lassen sich bearbeiten und rückgängig machen. Zu jeder Änderung können Sie sie auf die andere Seite kopieren, ersetzen oder löschen — direkt aus dem Vergleich heraus, ohne einen anderen Editor zu öffnen. Wenn Sie fertig sind, speichern Sie wie gewohnt.</p><div class="tip custom-block"><p class="custom-block-title">Ein Bild teilen</p><p>Wählen Sie eine Änderung aus und exportieren Sie sie als Bild: eine saubere zweispaltige Grafik, die sich leicht in eine Nachricht oder ein Review einfügen lässt. Das exportierte Bild ist frei von jedem Hinweis.</p></div><p>Weiter: <a href="./folders.html">ganze Ordner vergleichen</a>.</p>',14)])])}const m=i(s,[["render",d]]);export{b as __pageData,m as default};
